using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _service;

    public OrderServiceTests()
    {
        _service = new OrderService();
    }

    private static List<OrderItem> CreateItems(params (string name, decimal price, int qty)[] items) =>
        items.Select(i => new OrderItem { ProductName = i.name, Price = i.price, Quantity = i.qty }).ToList();

    #region CreateOrder

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectTotal()
    {
        // Arrange
        var items = CreateItems(("Widget", 10m, 2), ("Gadget", 25m, 1));

        // Act
        var order = _service.CreateOrder("cust-1", items);

        // Assert
        Assert.IsNotNull(order);
        Assert.AreEqual("cust-1", order.CustomerId);
        Assert.AreEqual(45m, order.Total);
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_AssignsNonEmptyId()
    {
        var items = CreateItems(("Widget", 10m, 1));

        var order = _service.CreateOrder("cust-1", items);

        Assert.IsNotNull(order.Id);
        Assert.IsNotEmpty(order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_SetsCreatedAtToUtcNow()
    {
        var before = DateTime.UtcNow;
        var items = CreateItems(("Widget", 10m, 1));

        var order = _service.CreateOrder("cust-1", items);

        var after = DateTime.UtcNow;
        Assert.IsInRange(order.CreatedAt, before, after);
    }

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        var items = CreateItems(("Widget", 10m, 1));

        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => _service.CreateOrder("cust-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _service.CreateOrder("cust-1", []));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [TestMethod]
    [DataRow(1, DisplayName = "Single item")]
    [DataRow(5, DisplayName = "Five items")]
    public void CreateOrder_StoresAllItems(int itemCount)
    {
        var items = Enumerable.Range(1, itemCount)
            .Select(i => new OrderItem { ProductName = $"Item{i}", Price = i, Quantity = 1 })
            .ToList();

        var order = _service.CreateOrder("cust-1", items);

        Assert.HasCount(itemCount, order.Items);
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsSameOrder()
    {
        var items = CreateItems(("Widget", 10m, 1));
        var created = _service.CreateOrder("cust-1", items);

        var retrieved = _service.GetOrder(created.Id);

        Assert.AreSame(created, retrieved);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        var result = _service.GetOrder("does-not-exist");

        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        var result = _service.GetOrdersByCustomer("cust-unknown");

        Assert.IsEmpty(result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_ReturnsOnlyMatchingOrders()
    {
        var items = CreateItems(("Widget", 10m, 1));
        var order1 = _service.CreateOrder("cust-1", items);
        _service.CreateOrder("cust-2", CreateItems(("Other", 5m, 1)));
        var order2 = _service.CreateOrder("cust-1", items);

        var result = _service.GetOrdersByCustomer("cust-1");

        Assert.HasCount(2, result);
        Assert.Contains(order1, result);
        Assert.Contains(order2, result);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithSingleOrder_ReturnsSingleElement()
    {
        var items = CreateItems(("Widget", 10m, 1));
        var order = _service.CreateOrder("cust-1", items);

        var result = _service.GetOrdersByCustomer("cust-1");

        var single = Assert.ContainsSingle(result);
        Assert.AreSame(order, single);
    }

    #endregion

    #region Total calculation

    [TestMethod]
    [DynamicData(nameof(TotalCalculationData))]
    public void CreateOrder_CalculatesCorrectTotal(
        string description, List<OrderItem> items, decimal expectedTotal)
    {
        var order = _service.CreateOrder("cust-1", items);

        Assert.AreEqual(expectedTotal, order.Total);
    }

    public static IEnumerable<object[]> TotalCalculationData =>
    [
        ["Single item, qty 1",
         CreateItems(("A", 10m, 1)), 10m],
        ["Single item, qty 3",
         CreateItems(("A", 10m, 3)), 30m],
        ["Multiple items",
         CreateItems(("A", 10m, 2), ("B", 5.50m, 4)), 42m],
    ];

    #endregion
}

